// Place search runs in Worker memory over a bundled copy of the places table (generated by
// scripts/build_places.py), so autocomplete and "nearest place" cost no D1 reads.
import data from './data.json';

type Row = [id: string, name: string, kind: number, muni: number, lat: number, lng: number, hint: string, aliases: string[]];

export interface Place {
  id: string;
  name: string;
  kind: string;
  municipality: string;
  province: string;
  hint: string | null;
  lat: number;
  lng: number;
}

const strip = (s: string) => s.normalize('NFD').replace(/\p{Mn}/gu, '').toLowerCase().replace(/\s+/g, ' ').trim();

interface Indexed {
  row: Row;
  name: string;
  terms: string[]; // normalized name plus aliases
  words: string[];
}

const rows = data.places as Row[];
// Where most adopters live: a small tiebreak so "naco" means Santo Domingo's Ensanche Naco before Baní's Naco.
const PROMINENT = new Set(['Distrito Nacional', 'Santo Domingo', 'Santiago'].map((n) => data.provinces.indexOf(n)));
const index: Indexed[] = rows.map((row) => {
  const name = strip(row[1]);
  return { row, name, terms: [name, ...row[7]], words: name.split(' ').filter((w) => w.length > 2) };
});
const byId = new Map(rows.map((r) => [r[0], r]));

function toPlace(r: Row): Place {
  const [muni, prov] = data.municipalities[r[3]] as [string, number];
  return { id: r[0], name: r[1], kind: data.kinds[r[2]], municipality: muni, province: data.provinces[prov], hint: r[6] || null, lat: r[4], lng: r[5] };
}

/** Prefix-first search: exact > name prefix > alias prefix > word prefix > contains. Towns and barrios rank above parajes. */
export function searchPlaces(query: string, limit = 8): Place[] {
  const q = strip(query);
  if (q.length < 2) return [];
  const scored: [number, Indexed][] = [];
  for (const item of index) {
    let score = 0;
    if (item.name === q) score = 100;
    else if (item.name.startsWith(q)) score = 80;
    else if (item.terms.includes(q)) score = 98;
    else if (item.terms.some((t) => t.startsWith(q))) score = 70;
    else if (item.words.some((w) => w.startsWith(q))) score = 50;
    else if (q.length >= 4 && item.name.includes(q)) score = 20;
    const prominent = PROMINENT.has((data.municipalities[item.row[3]] as [string, number])[1]) ? 4 : 0;
    if (score) scored.push([score + prominent - item.row[2] * 3 - item.name.length / 100, item]);
  }
  scored.sort((a, b) => b[0] - a[0]);
  return scored.slice(0, limit).map(([, i]) => toPlace(i.row));
}

export function placeById(id: string): Place | null {
  const r = byId.get(id);
  return r ? toPlace(r) : null;
}

/** Nearest place to a point, preferring barrios and towns over rural parajes when they're close enough. */
export function nearestPlace(lat: number, lng: number): Place | null {
  const k = Math.cos((lat * Math.PI) / 180);
  let best: Row | null = null;
  let bestD = Infinity;
  for (const r of rows) {
    const d = ((r[4] - lat) ** 2 + ((r[5] - lng) * k) ** 2) * (r[2] === 3 ? 1.6 : 1);
    if (d < bestD) (bestD = d), (best = r);
  }
  return best ? toPlace(best) : null;
}

/** Straight-line distance in km between two places (the same formula the app uses on the phone). */
export function distanceKm(a: Pick<Place, 'lat' | 'lng'>, b: Pick<Place, 'lat' | 'lng'>): number {
  const rad = (d: number) => (d * Math.PI) / 180;
  const h = Math.sin(rad(b.lat - a.lat) / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(rad(b.lng - a.lng) / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
}

/** Rough bounding box of the Dominican Republic. */
export const inDR = (lat: number, lng: number) => lat > 17.3 && lat < 20.1 && lng > -72.1 && lng < -68.2;

export const PLACES_ATTRIBUTION = data.attribution;
